INSERT INTO public.water_resources (slug, name, name_ru, name_en, description, description_en, location, region, country, latitude, longitude, status, irr, total_funding, category, object_type, capacity, year_established) VALUES
('OBJ-UZ-PS-001', 'Pumping Station No. 2', 'Насосная станция № 2', 'Pumping Station No. 2', 'Major pumping station serving Jizzakh region water distribution system', 'Electric pumps capacity: 3.5 MW. Serves 50,000+ population. Connected to regional pipeline system. Energy efficiency rating: B. Monthly inspections performed regularly.', 'Jizzakh', 'Jizzakh', 'Uzbekistan', 40.1033, 69.2233, 'operational', 17, 7760000, 'pumping_station', 'pumping_station', '45000 m³/day', 2010),
('OBJ-UZ-PS-002', 'Korovulbozor Station', 'Станция Коровульбозор', 'Korovulbozor Station', 'Regional water distribution center for Bukhara', NULL, 'Bukhara', 'Bukhara', 'Uzbekistan', 39.5755, 64.4229, 'operational', 15, 6190000, 'pumping_station', 'pumping_station', '32000 m³/day', 2008),
('OBJ-UZ-PS-003', 'Kuyumazar Main Station', 'Главная станция Кюмазара', 'Kuyumazar Main Station', 'Largest pumping capacity in Bukhara region', NULL, 'Bukhara', 'Bukhara', 'Uzbekistan', 39.8234, 64.3892, 'operational', 17, 7760000, 'pumping_station', 'pumping_station', '58000 m³/day', 2005),
('OBJ-UZ-PS-004', 'Kuyumazar Auxiliary Station', 'Вспомогательная станция Кюмазара', 'Kuyumazar Auxiliary Station', 'Modern auxiliary station with advanced control systems', NULL, 'Bukhara', 'Bukhara', 'Uzbekistan', 39.7892, 64.4123, 'operational', 22, 11970000, 'pumping_station', 'pumping_station', '28000 m³/day', 2012),
('OBJ-UZ-PS-005', 'Amu-Bukhara-1 Station', 'Станция Аму-Бухара-1', 'Amu-Bukhara-1 Station', 'Critical distribution junction for Amu Darya network', NULL, 'Bukhara', 'Bukhara', 'Uzbekistan', 39.6234, 64.5001, 'operational', 20, 9490000, 'pumping_station', 'pumping_station', '35000 m³/day', 2009),
('OBJ-UZ-WTF-001', 'Tashkent Water Treatment Complex', 'Комплекс очистки воды Ташкента', 'Tashkent Water Treatment Complex', 'Central water treatment facility serving Tashkent metropolitan area', NULL, 'Tashkent', 'Tashkent', 'Uzbekistan', 41.2995, 69.2401, 'operational', NULL, NULL, 'water_treatment_facility', 'water_treatment_facility', '800000 m³/day', 2003),
('OBJ-UZ-CAN-001', 'Bukhara-Karshi Canal', 'Канал Бухара-Карши', 'Bukhara-Karshi Canal', 'Major irrigation canal serving extensive agricultural areas', NULL, 'Bukhara-Kashkadarya', 'Bukhara-Kashkadarya', 'Uzbekistan', 39.35, 64.92, 'operational', NULL, NULL, 'irrigation_canal', 'irrigation_canal', NULL, 1976),
('OBJ-KZ-DAM-001', 'Chardara Dam', 'Плотина Чардара', 'Chardara Dam', 'Major dam serving irrigation and flood control', NULL, 'Kyzylorda Region', 'Kyzylorda Region', 'Kazakhstan', 45.2234, 68.5678, 'operational', NULL, 400000000, 'dam', 'dam', '3400000 m³', 1992),
('OBJ-KZ-RES-001', 'Bukhtarma Reservoir', 'Водохранилище Бухтарма', 'Bukhtarma Reservoir', 'Central Asia''s largest reservoir', NULL, 'East Kazakhstan Region', 'East Kazakhstan Region', 'Kazakhstan', 48.5234, 81.2345, 'operational', NULL, NULL, 'reservoir', 'reservoir', '49000000 m³', 1963),
('OBJ-TJ-DAM-001', 'Nurek Dam', 'Плотина Нурек', 'Nurek Dam', 'Central Asia''s tallest dam and largest hydroelectric facility', NULL, 'Rasht Valley', 'Rasht Valley', 'Tajikistan', 38.4521, 69.2345, 'operational', NULL, 300000000, 'dam', 'dam', '10500000 m³', 1979),
('OBJ-KG-LAK-001', 'Issyk-Kul Lake', 'Озеро Иссык-Куль', 'Issyk-Kul Lake', 'Strategic alpine water storage and ecosystem', NULL, 'Chuy and Issyk-Kul Regions', 'Chuy and Issyk-Kul Regions', 'Kyrgyzstan', 42.5, 77, 'operational', NULL, NULL, 'mountain_lake', 'mountain_lake', NULL, NULL),
('OBJ-KG-RES-001', 'Toktogul Reservoir', 'Водохранилище Токтогул', 'Toktogul Reservoir', 'Central Asia''s largest water storage and hydroelectric facility', NULL, 'Naryn River Basin', 'Naryn River Basin', 'Kyrgyzstan', 41.8678, 73.0234, 'operational', NULL, NULL, 'hydroelectric_reservoir', 'hydroelectric_reservoir', '19600000 m³', 1978),
('OBJ-ARAL-LAKE-001', 'Aral Sea', 'Аральское море', 'Aral Sea', 'Одна из крупнейших экологических катастроф XX века — Аральское море потеряло 90% объёма с 1960-х годов из-за перенаправления рек на орошение хлопка.', 'Аральское море — солёное озеро в Центральной Азии, разделённое между Казахстаном и Узбекистаном. В 1960-е годы было четвёртым по величине озером в мире. В результате советской ирригационной политики (перенаправление Амударьи и Сырдарьи на орошение хлопка) озеро потеряло более 90% объёма. Северное Аральское море частично восстанавливается благодаря дамбе Кок-Арал (Казахстан, 2005), Южное практически исчезло.', 'Kazakhstan / Uzbekistan', 'Kazakhstan / Uzbekistan', 'Kazakhstan/Uzbekistan', 45, 59.5, 'critical', NULL, NULL, 'lake_crisis', 'lake_crisis', NULL, NULL),
('OBJ-AMU-DARYA-001', 'Amu Darya River', 'Амударья', 'Amu Darya River', 'Главная река Центральной Азии. Основной источник воды для Узбекистана и Туркменистана. За последние годы расход упал с 82 до ~68 м³/сек из-за таяния ледников и орошения.', 'Амударья — трансграничная река, протекающая через Таджикистан, Узбекистан и Туркменистан. Питается таянием ледников Памира (74% стока). За последние 15 лет водные ресурсы на одного жителя сократились на 48%. К 2050 году расход снизится ещё на 15% из-за деградации ледников Памира.', 'Tajikistan / Uzbekistan / Turkmenistan', 'Tajikistan / Uzbekistan / Turkmenistan', 'Uzbekistan', 40, 63.5, 'critical', NULL, NULL, 'river', 'river', NULL, NULL),
('OBJ-SYR-DARYA-001', 'Syr Darya River', 'Сырдарья', 'Syr Darya River', 'Вторая по длине река Центральной Азии. Расход упал с ~400 м³/сек (естественный) до 48-50 м³/сек — потеря 90% стока из-за ирригации и климата. 25 млн человек зависят от этой реки.', 'Сырдарья берёт начало в горах Тянь-Шаня (Кыргызстан) и протекает через Таджикистан, Узбекистан и Казахстан. Питает Ферганскую долину — главный аграрный регион Центральной Азии. Хронический конфликт: Кыргызстан использует воду зимой для гидроэнергетики, Узбекистан и Казахстан — летом для ирригации.', 'Kyrgyzstan / Tajikistan / Uzbekistan / Kazakhstan', 'Kyrgyzstan / Tajikistan / Uzbekistan / Kazakhstan', 'Uzbekistan', 41, 67, 'critical', NULL, NULL, 'river', 'river', NULL, NULL),
('OBJ-MURRAY-DARLING-001', 'Murray-Darling Basin', 'Бассейн Мюррей-Дарлинг', 'Murray-Darling Basin', 'Australia''s most important river system feeds 40% of the nation''s farms, but chronic over-allocation has triggered devastating ''water wars'' between states, ecological collapse, and mass fish kills of over 1 million fish in 2019.', 'The Murray-Darling Basin covers 14% of Australia''s land mass and produces one-third of the nation''s food supply. Decades of unsustainable irrigation licenses issued far beyond the river''s natural yield have left the system in crisis. The 2012 Basin Plan allocated 2,750 GL/year for environmental flows, but implementation remains contested. The 2018–2019 drought caused catastrophic mass fish kills and cyanobacteria blooms. The basin is at the center of Australia''s most bitter political dispute over water rights.', 'New South Wales / Victoria / South Australia / Queensland', 'New South Wales / Victoria / South Australia / Queensland', 'Australia', -33.5, 143.5, 'critical', NULL, 4200000000, 'river', 'river', NULL, NULL),
('OBJ-COLORADO-RIVER-001', 'Colorado River / Lake Mead', 'Река Колорадо / Водохранилище Мид', 'Colorado River / Lake Mead', 'The Colorado River supplies water to 40 million people across 7 U.S. states and Mexico, but Lake Mead — the largest U.S. reservoir — fell to its lowest level ever recorded in July 2022, triggering federal water shortage declarations for the first time in history.', 'The Colorado River Compact of 1922 allocated 17.5 million acre-feet per year among seven states — a figure based on an unusually wet period. The actual average flow is closer to 12-13 million acre-feet. Since 2000, the basin has experienced the worst drought in 1,200 years (IPCC-confirmed megadrought). Lake Mead dropped to 27% capacity in July 2022. Federal Tier 1 and Tier 2 shortage declarations cut allocations to Arizona, Nevada, and Mexico. The 7-state Colorado River Agreement, renegotiated in 2023-2026, is the most significant U.S. water policy event in a century.', 'Colorado / Nevada / Arizona / California / Utah / Wyoming / New Mexico', 'Colorado / Nevada / Arizona / California / Utah / Wyoming / New Mexico', 'United States', 36.1, -114, 'critical', NULL, 8000000000, 'river', 'river', NULL, NULL),
('OBJ-LAKE-CHAD-001', 'Lake Chad', 'Озеро Чад', 'Lake Chad', 'Lake Chad has shrunk by approximately 90% since the 1960s — from 25,000 km² to under 2,500 km² — leaving 30 million people across 4 countries without a reliable water source and creating conditions for the Boko Haram insurgency.', 'Once the fourth-largest lake in Africa, Lake Chad has experienced catastrophic shrinkage due to climate change (reduced rainfall), increased irrigation withdrawals from the Chari and Logone rivers, and population pressure. The crisis has displaced over 2.4 million people and is widely cited by security analysts as a key driver of the Boko Haram conflict. The Lake Chad Basin Commission (LCBC) launched a $50 billion inter-basin water transfer proposal from the Congo River, though funding remains elusive. The UN Environment Programme classifies this as one of the world''s top 10 environmental crises.', 'Chad / Cameroon / Niger / Nigeria', 'Chad / Cameroon / Niger / Nigeria', 'Chad', 13.5, 14, 'critical', NULL, 50000000000, 'lake_crisis', 'lake_crisis', NULL, NULL),
('OBJ-MEKONG-RIVER-001', 'Mekong River', 'Река Меконг', 'Mekong River', 'The Mekong River sustains 70 million people and the world''s largest inland fishery, but China''s 11 upstream mega-dams are altering seasonal flood pulses, while drought in 2019 caused the river to fall to its lowest level in 100 years.', 'The Mekong is the lifeblood of Southeast Asia — its annual flood pulse fertilizes the Tonle Sap lake in Cambodia and drives rice agriculture across the Lower Mekong Basin. China has constructed 11 large dams on the upper Mekong (Lancang), controlling 70 billion cubic meters of storage. A 2020 Eyes on Earth study found that Chinese dams withheld water during the devastating 2019 Mekong drought while their reservoirs remained full. The Mekong River Commission lacks enforcement authority. Vietnam''s Mekong Delta — producing half of Vietnam''s rice and providing 90% of its rice exports — faces saltwater intrusion, land subsidence, and drastically reduced sediment flows.', 'China / Myanmar / Laos / Thailand / Cambodia / Vietnam', 'China / Myanmar / Laos / Thailand / Cambodia / Vietnam', 'Multi-country', 16, 104, 'critical', NULL, 5000000000, 'river', 'river', NULL, NULL),
('OBJ-INDUS-RIVER-001', 'Indus River System', 'Система реки Инд', 'Indus River System', 'The Indus is the world''s most stressed river system, supporting 300 million people in Pakistan and India, but glacial retreat in the Himalayas, disputed dam construction by India, and Pakistan''s explosive population growth threaten catastrophic water scarcity by 2040.', 'The Indus Waters Treaty (1960), brokered by the World Bank, divided the six Indus tributaries between India and Pakistan. Pakistan received the three western rivers (Indus, Jhelum, Chenab), India the three eastern ones. The treaty has survived three wars but now faces existential stress: India is building run-of-river dams on treaty rivers, Pakistan disputes multiple projects at the Permanent Indus Commission, and both nations are invoking treaty arbitration. Pakistan — one of the most water-insecure nations on Earth — loses 25% of its available water to inefficient irrigation while aquifers fall by 50 cm/year in Punjab. The 2022 floods submerged one-third of Pakistan, highlighting extreme hydrological volatility.', 'Pakistan / India / Afghanistan / China', 'Pakistan / India / Afghanistan / China', 'Pakistan', 27, 68.5, 'critical', NULL, 12000000000, 'river', 'river', NULL, NULL),
('OBJ-YELLOW-RIVER-001', 'Yellow River (Huang He)', 'Жёлтая река (Хуанхэ)', 'Yellow River (Huang He)', 'China''s ''Mother River'' ran completely dry for 267 days in 1997 and failed to reach the sea, an event that shocked the nation into action. Today, while drying episodes are managed, heavy metals and nitrate pollution affect 33% of the river''s length, threatening drinking water for 107 million people.', 'The Yellow River is China''s second-longest river and the cradle of Chinese civilization. It carried the most sediment of any river on Earth and built the North China Plain. The 1997 dry-out, when the river ceased flowing to the sea for 267 days, triggered China''s most significant water management reform. The Yellow River Conservancy Commission now manages diversions via the most sophisticated water rights trading system in Asia. However, heavy industrial pollution from coal mining, smelting, and petrochemicals has made over 33% of the river''s water unfit even for irrigation. Northern China''s food production — 55% of China''s wheat — depends on this system.', 'Qinghai / Sichuan / Gansu / Ningxia / Inner Mongolia / Shaanxi / Shanxi / Henan / Shandong', 'Qinghai / Sichuan / Gansu / Ningxia / Inner Mongolia / Shaanxi / Shanxi / Henan / Shandong', 'China', 37, 107, 'critical', NULL, 15000000000, 'river', 'river', NULL, NULL),
('OBJ-JORDAN-RIVER-001', 'Jordan River', 'Река Иордан', 'Jordan River', 'The Jordan River — one of the world''s most historically significant water bodies — has been reduced to just 2% of its natural flow. Over 98% of its water is diverted by Israel, Jordan, and Syria before reaching the Dead Sea, which is itself dropping 1 meter per year.', 'The Jordan River historically carried 1.2–1.4 billion m³/year to the Dead Sea. Today, less than 30 million m³ — only 2% — actually flows through the Lower Jordan. Israel''s National Water Carrier diverts 400 million m³/year from the Sea of Galilee; Jordan''s East Ghor Canal diverts from the Yarmouk; Syria and Lebanon divert from headwater tributaries. The result is a barely flowing, heavily salinized and polluted waterway that carries mostly sewage and agricultural runoff. The lower Jordan''s salinity has risen from 250 ppm to over 1,500 ppm. Restoration to 300 million m³/year annual flow is estimated to cost $5–10 billion and would require a new Israeli-Palestinian-Jordanian water agreement.', 'Israel / Palestine / Jordan / Lebanon / Syria', 'Israel / Palestine / Jordan / Lebanon / Syria', 'Israel', 32, 35.5, 'critical', NULL, 10000000000, 'river', 'river', NULL, NULL),
('OBJ-NILE-DELTA-001', 'Nile River Delta', 'Дельта Нила', 'Nile River Delta', 'The Nile Delta — home to 50 million Egyptians and producing 60% of Egypt''s agricultural output — faces triple-threat: saltwater intrusion from rising Mediterranean, subsidence due to loss of Nile sediment blocked by Aswan Dam, and Ethiopia''s GERD mega-dam threatening to reduce Egypt''s Nile allocation by 25%.', 'The Nile Delta is one of the world''s oldest and most densely populated agricultural regions, but it is under existential threat. The Aswan High Dam (1970) blocks 98% of the Nile''s natural sediment load, causing the delta to subside by 3–8 mm/year while sea levels rise. NASA satellite data shows 60% of the northern delta is now below sea level. Saltwater has intruded up to 100 km inland, contaminating aquifers and destroying agricultural land. Ethiopia''s Grand Ethiopian Renaissance Dam (GERD), filling since 2020, is the flashpoint of a potential water war: Egypt and Sudan have declared it a national security issue. The 1959 Nile Waters Agreement gave Egypt 55.5 billion m³/year; Ethiopia, as an upstream state, claims it has no obligation under this colonial-era treaty.', 'Northern Egypt', 'Northern Egypt', 'Egypt', 30.8, 31, 'critical', NULL, 20000000000, 'river', 'river', NULL, NULL),
('OBJ-GANGES-RIVER-001', 'Ganges River', 'Река Ганг', 'Ganges River', 'The Ganges — sacred to 1 billion Hindus and the drinking water source for 500 million people — is ranked among the world''s 5 most polluted rivers. The Gangotri Glacier feeding it has retreated 30 meters per year since 1971, while industrial and sewage effluents make its downstream stretches biologically dead.', 'The Ganges basin is home to over 500 million people — the most densely populated river basin on Earth. The river is simultaneously over-extracted (330 irrigation barrages) and severely polluted (1.4 billion liters of raw sewage enter daily). The Gangotri Glacier, the river''s primary Himalayan source, has retreated 22 km since 1780 and is losing mass at an accelerating rate. India''s National Mission for Clean Ganga (NMCG) has invested over $4.5 billion since 2016 but pollution levels remain critically elevated in most urban stretches. The river is legally recognized as a living entity in India (Uttarakhand High Court, 2017) though this status was overturned by the Supreme Court pending legislation. Fecal coliform levels in Varanasi reach 600,000 MPN/100 ml — 30,000 times the WHO safe limit.', 'Uttarakhand / Uttar Pradesh / Bihar / Jharkhand / West Bengal', 'Uttarakhand / Uttar Pradesh / Bihar / Jharkhand / West Bengal', 'India', 25.5, 83, 'critical', NULL, 25000000000, 'river', 'river', NULL, NULL),
('OBJ-DEAD-SEA-001', 'Dead Sea', 'Мёртвое море', 'Dead Sea', 'The Dead Sea is shrinking at 1 meter per year — it has lost 40% of its surface area since 1960. The main cause is 98% diversion of the Jordan River''s water before it reaches the sea. Over 6,000 sinkholes have appeared along the northern shores, swallowing roads and infrastructure.', 'The Dead Sea is the lowest point on Earth at 430 meters below sea level, but it is dropping by approximately 1 meter annually. The shoreline has receded by several kilometers since the 1960s. The primary cause is near-total diversion of the Jordan River (which once delivered 1.3 billion m³/year) and industrial extraction of minerals by Dead Sea Works (Israel) and Arab Potash Company (Jordan), which extract potash and bromine. The evaporation ponds of these companies cover the southern basin entirely. Over 6,000 sinkholes have opened along the northern shores as fresh groundwater dissolves ancient underground salt layers exposed by the falling lake. The proposed Red Sea-Dead Sea Water Conveyance canal ($11 billion, 180 km) would pipe Red Sea water northward to replenish the Dead Sea, but the project has been stalled by geopolitical tensions since 2021.', 'Israel / Palestine / Jordan', 'Israel / Palestine / Jordan', 'Israel', 31.5, 35.5, 'critical', NULL, 11000000000, 'lake_crisis', 'lake_crisis', NULL, NULL),
('OBJ-OGALLALA-AQUIFER-001', 'Ogallala Aquifer', 'Водоносный горизонт Огаллала', 'Ogallala Aquifer', 'The Ogallala Aquifer is the world''s largest freshwater aquifer, underlying 450,000 km² of the U.S. Great Plains and supplying 30% of all U.S. groundwater for irrigation. It is being depleted 50 times faster than it can recharge — some parts of Kansas, Texas, and Oklahoma may run out within 25 years.', 'The Ogallala (High Plains) Aquifer stretches beneath 8 U.S. states and has enabled a $20 billion/year agricultural economy growing corn, wheat, sorghum, and cattle feed. But the water accumulates over millions of years and recharges at only 0.5–2.5 cm/year — while current extraction runs at 1–3 meters/year. Since intensive irrigation began in the 1950s, the water table has dropped by more than 100 feet in parts of Texas and Kansas. At current depletion rates, parts of the Southern High Plains could be 70% depleted within 50 years, ending large-scale agriculture. The USGS estimates 69 billion acre-feet remain compared to the original 174 billion — a 60% decline in stored water. No large-scale recharge technology exists; the only solutions are demand reduction, fallowing, and drip irrigation conversion.', 'South Dakota / Nebraska / Wyoming / Colorado / Kansas / Oklahoma / New Mexico / Texas', 'South Dakota / Nebraska / Wyoming / Colorado / Kansas / Oklahoma / New Mexico / Texas', 'United States', 38, -101.5, 'critical', NULL, 8000000000, 'reservoir', 'reservoir', NULL, NULL),
('OBJ-SAO-FRANCISCO-001', 'São Francisco River', 'Река Сан-Франциску', 'São Francisco River', 'The São Francisco River — Brazil''s ''River of National Integration'' — has lost 30% of its average flow since 2012 due to mega-droughts and deforestation in the Cerrado headwaters, threatening 15 million people in Brazil''s semi-arid northeast who depend on the River Integration Project.', 'The São Francisco River connects Brazil''s relatively water-rich southeast to the chronically drought-affected semi-arid northeast. The $4 billion São Francisco River Integration Project (PISF) — a 477 km canal system — was designed to supply water from the river to 12 million people in Ceará, Paraíba, Pernambuco, and Rio Grande do Norte. However, the project has been dogged by controversy: critics argue it diverts water from a river already under stress, while proponents say it is essential for ending drought-related suffering. The 2012-2017 megadrought — the worst in 80 years — reduced river flow to record lows and caused Sobradinho Reservoir (the world''s largest man-made lake by area at 4,214 km²) to fall to just 1.7% capacity in 2017. Deforestation in the Cerrado headwaters, where 46% of the basin''s vegetation has been cleared, is permanently reducing the river''s flow.', 'Minas Gerais / Bahia / Pernambuco / Alagoas / Sergipe', 'Minas Gerais / Bahia / Pernambuco / Alagoas / Sergipe', 'Brazil', -10.5, -40.5, 'critical', NULL, 6000000000, 'river', 'river', NULL, NULL),
('OBJ-VOLGA-RIVER-001', 'Volga River', 'Река Волга', 'Volga River', 'The Volga — Europe''s longest river and Russia''s national symbol — has been transformed into a chain of reservoirs by 8 major dams since the 1950s. The resulting loss of floodplain function, combined with industrial and agricultural pollution, has caused Caspian Sea sturgeon populations to collapse by 97%.', 'The Volga drains 38% of European Russia and supports 45% of Russia''s industrial production and 50% of its agricultural output from the river basin. The Soviet ''Volga-Kama Cascade'' of 8 major hydroelectric dams created a chain of reservoirs stretching for 3,000 km and generating 14 GW of electricity. However, the dams blocked sturgeon migration (cutting off 80% of spawning grounds), eliminated seasonal flood pulses needed for wetland ecology, and accelerated industrial pollution accumulation in reservoirs. The Caspian Sea — into which the Volga delivers 80% of its inflow — has fallen by 3 meters since 1978 and is expected to lose 25–74% of its surface area by 2100. Russian government program ''Ecology of Volga'' (2019-2024, $5B) aims to reduce pollutant discharge by 2.5 times, but industrial lobbying has slowed implementation.', 'Tver / Yaroslavl / Kostroma / Ivanovo / Nizhny Novgorod / Chuvashia / Mari El / Tatarstan / Ulyanovsk / Samara / Saratov / Volgograd / Astrakhan', 'Tver / Yaroslavl / Kostroma / Ivanovo / Nizhny Novgorod / Chuvashia / Mari El / Tatarstan / Ulyanovsk / Samara / Saratov / Volgograd / Astrakhan', 'Russia', 54, 47, 'critical', NULL, 10000000000, 'river', 'river', NULL, NULL);
